import{_ as a,o as s,c as n,a2 as i}from"./chunks/framework.BS0bAV7E.js";const u=JSON.parse('{"title":"Building and packaging","description":"","frontmatter":{},"headers":[],"relativePath":"dev/build.md","filePath":"dev/build.md"}'),t={name:"dev/build.md"};function o(l,e,r,c,d,p){return s(),n("div",null,[...e[0]||(e[0]=[i(`<h1 id="building-and-packaging" tabindex="-1">Building and packaging <a class="header-anchor" href="#building-and-packaging" aria-label="Permalink to &quot;Building and packaging&quot;">​</a></h1><p>The developer view of the build system. For the user-level guide see <a href="./../root/BUILDING.html">BUILDING.md</a> at the repository root - this page adds the developer-workflow details.</p><h2 id="targets-you-will-actually-use" tabindex="-1">Targets you will actually use <a class="header-anchor" href="#targets-you-will-actually-use" aria-label="Permalink to &quot;Targets you will actually use&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>make -j$(nproc) kernel     # fast inner loop: ELF only</span></span>
<span class="line"><span>make iso                   # + bootable ISO</span></span>
<span class="line"><span>make test                  # host unit tests (no QEMU needed)</span></span>
<span class="line"><span>make run-bios              # boot the ISO</span></span>
<span class="line"><span>make clean                 # start fresh</span></span>
<span class="line"><span>make reproducible-check    # two clean builds -&gt; byte-identical ELF</span></span></code></pre></div><h2 id="the-compile-cache-makes-the-inner-loop-fast" tabindex="-1">The compile cache makes the inner loop fast <a class="header-anchor" href="#the-compile-cache-makes-the-inner-loop-fast" aria-label="Permalink to &quot;The compile cache makes the inner loop fast&quot;">​</a></h2><p><code>tools/oc_cc.sh</code> wraps every compile rule with a content-addressed cache: key = compiler identity + full flag set + source content hash</p><ul><li>the content hashes of every header dependency (the dependency probe is a <code>gcc -MM -MG</code> pass with the -MMD/-MP flags stripped so the two never fight).</li></ul><ul><li>Cold build of the release tree: 46.6 s. Warm: 14.4 s (186/186 hits, 3.2x). Warm objects are byte-identical to cold ones.</li><li><code>make cache-stats</code> / <code>make cache-clear</code> manage it.</li><li>A stale cache entry is impossible: any header edit changes the key.</li></ul><h2 id="version-and-build-number" tabindex="-1">Version and build number <a class="header-anchor" href="#version-and-build-number" aria-label="Permalink to &quot;Version and build number&quot;">​</a></h2><ul><li><code>OC_RELEASE_VERSION</code> defaults to the version literal in the Makefile (<code>2.1.0</code> while the 2.1.0 freeze is on; see <a href="./../release/versioning.html">versioning</a>); override on the command line (<code>make OC_RELEASE_VERSION=2.1.1-test1 iso</code>) and it ends up in the banner, <code>uname -a</code>, the OTA manifest and the ISO volume id.</li><li>The build number is the commit count plus the permanent +21 alignment offset (see <a href="./../release/versioning.html">versioning</a>; <code>OC_KERNEL_BUILD_OFFSET := 21</code> in the Makefile) - it feeds <code>uname</code> and the update.json &quot;build&quot; field at release time.</li></ul><h2 id="packaging-determinism" tabindex="-1">Packaging determinism <a class="header-anchor" href="#packaging-determinism" aria-label="Permalink to &quot;Packaging determinism&quot;">​</a></h2><ul><li><strong>SRC zip</strong> (<code>make src-zip</code>): a <code>git archive</code> - tree order, commit mtimes, index permissions; byte-identical for the same commit. Excludes the website/out/build/deliverables trees via <code>SRC_EXCLUDE</code>.</li><li><strong>OTA</strong> (<code>make ota</code>): kernel ELF + manifest; the manifest carries the build day (UTC) so the package is byte-reproducible within a day.</li><li><strong>ELF</strong>: no <strong>DATE</strong>/<strong>TIME</strong>/<strong>TIMESTAMP</strong> anywhere in the tree (a make gate greps for them), fixed link order, <code>strip --strip-debug</code> removes path-bearing sections.</li></ul><h2 id="multi-config-and-cross-builds-developer-notes" tabindex="-1">Multi-config and cross builds (developer notes) <a class="header-anchor" href="#multi-config-and-cross-builds-developer-notes" aria-label="Permalink to &quot;Multi-config and cross builds (developer notes)&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>make defconfig          # .config with everything on</span></span>
<span class="line"><span>make menuconfig         # interactive (tools/oc_menuconfig.sh)</span></span>
<span class="line"><span>make CONFIG_TUI=n CONFIG_CHINESE=n iso    # no-TUI/CN image (oc&gt; 90)</span></span>
<span class="line"><span>make ARCH=arm64         # PL011 bring-up shell ELF</span></span>
<span class="line"><span>make ARCH=riscv         # NS16550A bring-up shell ELF</span></span></code></pre></div><p>The configurator generates <code>core/generated/config_gen.h</code> with compare-guarded macros; disabled features route to real ASCII equivalents (console_cn -&gt; screen_console), never to deleted code. The GNU make <code>%</code> wildcard limitation (only the first <code>%</code> in a pattern matches) is why the TUI/Chinese source filters look the way they do - do not &quot;simplify&quot; them.</p><h2 id="scriptable-api" tabindex="-1">Scriptable API <a class="header-anchor" href="#scriptable-api" aria-label="Permalink to &quot;Scriptable API&quot;">​</a></h2><p><code>tools/build.sh</code> doubles as a function library:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>source tools/build.sh</span></span>
<span class="line"><span>build_all; build_iso; config_load; cache_lookup; cross_compile ...</span></span>
<span class="line"><span>tools/build.sh api-selftest     # verifies the 8 spec&#39;d interfaces</span></span></code></pre></div><p>Release automation (see <a href="./../release/process.html">../release/process.md</a>) composes these instead of parsing make output.</p>`,19)])])}const m=a(t,[["render",o]]);export{u as __pageData,m as default};
